---FreshUI
function CatHouseResultEstimateResultContentNode:FreshUI(data, name, showGroupType)
    ----------------------
    --- 刷新标题 Variation -> ShowGroupType.Variation
    local isShowContent = showGroupType < Variation
    self.ImgBgTitle.Status = isShowContent and 1 or 2

    self:FreshContent(data, name, showGroupType)

end

function CatHouseResultEstimateResultContentNode:FreshContent(data, name, showGroupType)
    local count    = #data
    local isEmpty  = count == 0
    
    KTool.SetActive(self.None.gameObject,     isEmpty)
    KTool.SetActive(self.Content.gameObject,  not isEmpty)
    KTool.SetActive(self.IconMask.gameObject, not isEmpty)
    if isEmpty then
        self.NoneText.text = localize("本次不会出现_name_基因", {_name_ = name})
        return 
    end

    self.TitleText.text = localize("可能出现的_name_", {_name_ = name})
    ---@type CatHouseCatDataVo[]
    self.dataList = data
    self.TitleImgIcon:LoadSprite(data[1].icon)
    
    local loopList = self.DataList
    if not loopList.IsListViewInit then
        loopList:InitGridView(count, Bind(self, self.OnGetItemByIndex))
    else
        GameUtils.ReloadData(loopList, count)
    end
end

function CatHouseResultEstimateResultContentNode:OnGetItemByIndex(listView, index)
    if index < 0 then
        return nil
    end
    local cell = listView:NewListViewItem(CellName)
    local dataNode = cell.transform:Find("CatHouseBtnDataNode")
    if dataNode then
        local position = index + 1
        local data = self.dataList[position]
        ---@type CatHouseDataNode
        local nodeEnv = CfUtils.GetLuaScr(dataNode, CellEnvPath)
        if not isNull(nodeEnv) then
            local geneId = data.id
            local geneData = {geneId = geneId}
            nodeEnv:FreshChild(geneData)
            nodeEnv:SetBtnCallBack(function ()
                CatHouseMgr:GetInstance():ShowCatHousDataDetailsNode(dataNode.gameObject, geneData)
            end)
        end
    end
    return cell
end

